// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract PaymentProcessor is ReentrancyGuard, Ownable {
    struct PaymentRequest {
        address payable recipient;
        uint256 amount;
        uint256 nonce;
        bytes32 commitHash;
        uint256 revealDeadline;
        bool executed;
        bool cancelled;
    }

    mapping(bytes32 => PaymentRequest) public payments;
    mapping(address => uint256) public nonces;
    mapping(address => uint256) public balances;

    uint256 public constant REVEAL_WINDOW = 2 hours;
    uint256 public constant MIN_COMMIT_AMOUNT = 0.01 ether;

    bool public circuitBreakerActive;
    uint256 public dailyVolume;
    uint256 public dailyVolumeLimit;
    uint256 public lastResetTimestamp;
    uint256 public emergencyThreshold;

    event PaymentCommitted(bytes32 indexed paymentId, address indexed sender, bytes32 commitHash);
    event PaymentRevealed(bytes32 indexed paymentId, address indexed recipient, uint256 amount);
    event PaymentExecuted(bytes32 indexed paymentId);
    event CircuitBreakerTriggered(uint256 volume, uint256 limit);
    event CircuitBreakerReset();

    modifier whenNotPaused() {
        require(!circuitBreakerActive, "Circuit breaker active");
        _;
    }

    constructor(uint256 _dailyLimit, uint256 _emergencyThreshold) {
        dailyVolumeLimit = _dailyLimit;
        emergencyThreshold = _emergencyThreshold;
        lastResetTimestamp = block.timestamp;
    }

    function deposit() external payable {
        balances[msg.sender] += msg.value;
    }

    function _resetDailyVolumeIfNeeded() internal {
        if (block.timestamp >= lastResetTimestamp + 1 days) {
            dailyVolume = 0;
            lastResetTimestamp = block.timestamp;
        }
    }

    function _checkCircuitBreaker(uint256 amount) internal {
        _resetDailyVolumeIfNeeded();
        dailyVolume += amount;
        if (dailyVolume > dailyVolumeLimit) {
            circuitBreakerActive = true;
            emit CircuitBreakerTriggered(dailyVolume, dailyVolumeLimit);
        }
    }

    function commitPayment(bytes32 _commitHash) external whenNotPaused returns (bytes32) {
        uint256 currentNonce = nonces[msg.sender]++;
        bytes32 paymentId = keccak256(abi.encodePacked(msg.sender, currentNonce));

        payments[paymentId] = PaymentRequest({
            recipient: payable(address(0)),
            amount: 0,
            nonce: currentNonce,
            commitHash: _commitHash,
            revealDeadline: block.timestamp + REVEAL_WINDOW,
            executed: false,
            cancelled: false
        });

        emit PaymentCommitted(paymentId, msg.sender, _commitHash);
        return paymentId;
    }

    function revealPayment(
        bytes32 _paymentId,
        address payable _recipient,
        uint256 _amount,
        bytes32 _salt
    ) external whenNotPaused nonReentrant {
        PaymentRequest storage payment = payments[_paymentId];
        require(!payment.executed, "Already executed");
        require(!payment.cancelled, "Payment cancelled");
        require(block.timestamp <= payment.revealDeadline, "Reveal window expired");

        bytes32 expectedHash = keccak256(abi.encodePacked(_recipient, _amount, _salt));
        require(expectedHash == payment.commitHash, "Invalid reveal");

        require(_amount >= MIN_COMMIT_AMOUNT, "Below minimum");
        require(balances[msg.sender] >= _amount, "Insufficient balance");

        payment.recipient = _recipient;
        payment.amount = _amount;

        emit PaymentRevealed(_paymentId, _recipient, _amount);
    }

    function executePayment(bytes32 _paymentId) external whenNotPaused nonReentrant {
        PaymentRequest storage payment = payments[_paymentId];
        require(!payment.executed, "Already executed");
        require(!payment.cancelled, "Payment cancelled");
        require(payment.recipient != address(0), "Not revealed");
        require(payment.amount > 0, "Invalid amount");

        address sender = _recoverSender(_paymentId, payment.nonce);
        require(balances[sender] >= payment.amount, "Insufficient balance");

        payment.executed = true;
        balances[sender] -= payment.amount;

        _checkCircuitBreaker(payment.amount);

        (bool success, ) = payment.recipient.call{value: payment.amount}("");
        require(success, "Transfer failed");

        emit PaymentExecuted(_paymentId);
    }

    function _recoverSender(bytes32 _paymentId, uint256 _nonce) internal pure returns (address) {
        // Recover sender from paymentId construction
        // paymentId = keccak256(abi.encodePacked(sender, nonce))
        // This is a lookup helper - in production would use mapping
        return address(uint160(uint256(_paymentId) >> 96));
    }

    function cancelPayment(bytes32 _paymentId) external {
        PaymentRequest storage payment = payments[_paymentId];
        require(!payment.executed, "Already executed");

        bytes32 expectedId = keccak256(abi.encodePacked(msg.sender, payment.nonce));
        require(expectedId == _paymentId, "Not payment owner");

        payment.cancelled = true;
    }

    function getPaymentDetails(bytes32 _paymentId) external view returns (
        address recipient,
        uint256 amount,
        uint256 revealDeadline,
        bool executed,
        bool cancelled
    ) {
        PaymentRequest storage p = payments[_paymentId];
        return (p.recipient, p.amount, p.revealDeadline, p.executed, p.cancelled);
    }

    function resetCircuitBreaker() external onlyOwner {
        circuitBreakerActive = false;
        dailyVolume = 0;
        lastResetTimestamp = block.timestamp;
        emit CircuitBreakerReset();
    }

    function updateLimits(uint256 _newLimit, uint256 _newThreshold) external onlyOwner {
        dailyVolumeLimit = _newLimit;
        emergencyThreshold = _newThreshold;
    }

    receive() external payable {
        balances[msg.sender] += msg.value;
    }
}
